    W = len(grid[0])
    out = [row[:] for row in grid]

    # Target color (5 in test, 1 in demo)
    target = 5
    intruder_pos = set((r, c) for r in range(H) for c in range(W) if grid[r][c] == target)

    # Positions to fill with target: original + 4 reflections
    positions_to_fill = {}
    for (r, c) in intruder_pos:
        fill_positions = {
            (r, c),
            (H - 1 - r, c),
            (r, W - 1 - c),
            (H - 1 - r, W - 1 - c)
        }
        positions_to_fill.update(fill_positions)

    # Fill 0s at these positions with target
    for (r, c) in positions_to_fill:
        if 0 <= r < H and 0 <= c < W:
            if out[r][c] == 0:
                out[r][c] = target

    return out
