def transform(grid):
    H, W = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    target = 5

    # Find all positions with target color
    for r in range(H):
        for c in range(W):
            if grid[r][c] == target:
                # Original position
                if out[r][c] == target or out[r][c] == 0:
                    out[r][c] = target
                # Vertical mirror (flip rows)
                v_r = H - 1 - r
                h_c = c
                if out[v_r][h_c] == 0:
                    out[v_r][h_c] = target
                # Horizontal mirror (flip cols)
                v_r = r
                v_c = W - 1 - c
                if out[v_r][v_c] == 0:
                    out[v_r][v_c] = target
                # Center mirror (both)
                v_r, v_c = H - 1 - r, W - 1 - c
                if out[v_r][v_c] == 0:
                    out[v_r][v_c] = target

    return out
