def transform(grid):
    H, W = len(grid), len(grid[0])
    out = [[grid[r][c] for c in range(W)] for r in range(H)]

    # Target color
    target = 0
    for color in range(10):
        if color == 0: continue
        if any(grid[r][c] == color and grid[r][c] != (8 if 8 in grid[0][:3] else 9) for r in range(H) for c in range(W)):
            target = color
            break

    # Apply 3-fold rotational symmetry + mirror
    # For each position in the pattern, reflect across center
    positions = set()
    for r in range(H):
        for c in range(W):
            if grid[r][c] == target:
                positions.add((r, c))

    for (r, c) in positions:
        positions.add((H-1-r, c))
        positions.add((r, W-1-c))
        positions.add((H-1-r, W-1-c))

    for r, c in positions:
        if 0 <= r < H and 0 <= c < W:
            if out[r][c] == 0:
                out[r][c] = target

    return out
